n[_ngcontent-%COMP%] {\n    border-width: 2px;\n  }\n  .property-rating[_ngcontent-%COMP%] {\n    background: rgba(0, 0, 0, 0.9);\n  }\n  .search-error[_ngcontent-%COMP%] {\n    border-left-width: 6px;\n  }\n}\n/*# sourceMappingURL=data:application/json;charset=utf-8;base64, */"]
